/* Typography */
h1, h2, h3, .serif-heading { font-family: 'Cormorant Garamond', serif; color: #111111; }
body, p, a, span, .sans-body { font-family: 'Inter', sans-serif; }

/* Buttons */
.btn-primary { background-color: #111111 !important; color: #FFFFFF !important; border: 1px solid #111111 !important; transition: all 0.3s ease; }
.btn-primary:hover { background-color: #333333 !important; border-color: #333333 !important; }
.btn-outline { background-color: transparent !important; color: #111111 !important; border: 1px solid #111111 !important; }
.btn-outline:hover { background-color: #111111 !important; color: #FFFFFF !important; }

/* Hero */
.hero-overlay { background: rgba(0,0,0,0.4); }

/* How It Works (Come Lavoriamo) */
.how-it-works-grid { display: flex; align-items: flex-start; justify-content: space-between; gap: 2rem; }
.step-item { flex: 1; display: flex; flex-direction: column; position: relative; }
.step-number { font-size: 3rem; font-weight: 300; font-family: 'Cormorant Garamond', serif; color: #111111; margin-bottom: 1rem; }
.step-title { font-weight: 600; margin-bottom: 0.5rem; font-size: 1.25rem; }
.step-item:not(:last-child)::after { content: '>'; position: absolute; top: 1.5rem; right: -1.5rem; font-size: 1.5rem; color: #111111; opacity: 0.5; font-weight: 300; }

/* Editorial Section (Lo Studio) */
.editorial-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.editorial-image { width: 100%; height: 100%; object-fit: cover; }

/* Projects Grid */
.projects-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.project-card { display: flex; flex-direction: column; border: none; background: transparent; }
.project-image-wrapper { width: 100%; aspect-ratio: 4/3; overflow: hidden; margin-bottom: 1rem; }
.project-image { width: 100%; height: 100%; object-fit: cover; }
.project-title { font-family: 'Cormorant Garamond', serif; font-size: 1.5rem; margin-bottom: 0.25rem; }
.project-location { color: #666; font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 1rem; }
.project-link { font-weight: 600; font-size: 0.875rem; color: #111111; display: inline-flex; align-items: center; }

/* Digital Journey */
.digital-journey-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.features-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
.feature-card { padding: 1.5rem; background: #FFFFFF; border-radius: 0; box-shadow: 0 4px 6px rgba(0,0,0,0.02); display: flex; flex-direction: column; gap: 1rem; }
.feature-icon { font-size: 1.5rem; color: #111111; }

/* Magazine Section */
.magazine-row { display: flex; flex-direction: column; gap: 1.5rem; margin-top: 2rem; }
@media(min-width: 768px) { .magazine-row { flex-direction: row; justify-content: space-between; } }
.magazine-card { display: flex; align-items: center; gap: 1.5rem; flex: 1; }
.magazine-thumb { width: 100px; height: 100px; object-fit: cover; flex-shrink: 0; }
.magazine-content { display: flex; flex-direction: column; gap: 0.5rem; }
.magazine-title { font-weight: 600; font-size: 1rem; line-height: 1.4; }

/* Final CTA Section */
.final-cta-section { background-color: #121212; color: #FFFFFF; padding: 6rem 0; }
.final-cta-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 2rem; align-items: center; }
.final-cta-title { font-family: 'Cormorant Garamond', serif; font-size: 3rem; line-height: 1.2; color: #FFFFFF; }
.final-cta-section .btn-primary { background-color: #FFFFFF !important; color: #121212 !important; border-color: #FFFFFF !important; }
.final-cta-section .btn-primary:hover { background-color: #E5E5E5 !important; }

/* Footer */
.site-footer { background-color: #121212; color: #FFFFFF; padding: 4rem 0 2rem; font-size: 0.875rem; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 2rem; margin-bottom: 4rem; }
.footer-logo { font-family: 'Cormorant Garamond', serif; font-size: 2rem; margin-bottom: 1rem; color: #FFFFFF; }
.footer-col-title { font-weight: 600; color: #888888; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 1.5rem; font-size: 0.75rem; }
.footer-links { display: flex; flex-direction: column; gap: 0.75rem; }
.footer-links a { color: #CCCCCC; text-decoration: none; transition: color 0.2s; }
.footer-links a:hover { color: #FFFFFF; }
.footer-bottom { border-top: 1px solid #333333; padding-top: 2rem; display: flex; justify-content: space-between; color: #888888; }
